BEGIN;
DO $$
#variable_conflict use_variable
DECLARE admin_id uuid; seller uuid:=gen_random_uuid(); prod uuid:=gen_random_uuid(); item uuid:=gen_random_uuid(); wh uuid:=gen_random_uuid(); cid uuid; rid uuid:=gen_random_uuid(); oid uuid; args jsonb; followup jsonb; result jsonb; again jsonb; policy uuid; other_id uuid:=gen_random_uuid(); wrong_order uuid; cancel_order uuid; pay1 uuid; pay2 uuid; pay3 uuid; cashpay uuid; credit_request_id uuid:=gen_random_uuid(); pay_payload jsonb; ledger_count bigint; legacy_order uuid:=gen_random_uuid(); legacy_payment uuid; legacy_actor uuid; stock_before text; freight_order uuid; portal_freight boolean; freight_case jsonb; freight_args jsonb; freight_followup jsonb; cur text; portal boolean; before_count bigint; offered numeric; quote jsonb;
BEGIN
 SELECT id INTO admin_id FROM public.profiles WHERE email='tirzenaadm@gmail.com';
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 INSERT INTO auth.users(id,email,created_at) VALUES(other_id,'credit-other-'||other_id||'@example.invalid',now());
 UPDATE public.profiles SET is_active=true WHERE id=other_id;
 INSERT INTO public.user_roles(user_id,role) VALUES(other_id,'vendedor') ON CONFLICT DO NOTHING;

 INSERT INTO auth.users(id,email,raw_user_meta_data,created_at) VALUES(seller,'seller-pdv-test-'||seller||'@example.invalid','{}',now());
 UPDATE public.profiles SET is_active=true WHERE id=seller;
 INSERT INTO public.user_roles(user_id,role) VALUES(seller,'vendedor') ON CONFLICT DO NOTHING;
 INSERT INTO public.products(id,name,is_active,is_demo) VALUES(prod,'Seller Pdv controlled product',true,true);
 INSERT INTO public.product_users(product_id,user_id) VALUES(prod,seller);
 INSERT INTO public.inventory_items(id,product_id,name,unit,currency,cost,price,quantity,reserved,max_discount_percent,freight_py_percent,freight_sp_percent,freight_other_brazil_percent,is_active,is_demo) VALUES(item,prod,'Seller Pdv controlled item','UN','BRL',50,100,20,0,10,90,90,90,true,true);
 INSERT INTO public.warehouses(id,name,city,state,level,is_active) VALUES(wh,'Seller Pdv controlled warehouse','Test','SP','principal',true);
 INSERT INTO public.warehouse_inventory(warehouse_id,item_id,quantity,reserved) VALUES(wh,item,20,0);
 INSERT INTO public.integral_member_rules(user_id,general_access) VALUES(seller,true);
 INSERT INTO public.warehouse_user_assignments(user_id,product_id,warehouse_id,created_by) VALUES(seller,prod,wh,admin_id);
 INSERT INTO public.integral_division_access(user_id,system_code,can_view,can_write) VALUES(seller,'vendas_estaduais',true,true);
 policy:=public.remuneration_save_policy(NULL,jsonb_build_object('name','Seller PDV controlled policy','member_ids',jsonb_build_array(seller),'definition',jsonb_build_object('rules',jsonb_build_array(jsonb_build_object('kind','commission','type','percent','amount',5,'basis','sale','currency','BRL','period','per_sale','item_ids',jsonb_build_array(item))))),'Controlled seller PDV validation');
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 result:=public.integral_seller_create_pdv_customer('{"name":"Cliente controlado","phone":"32999999999","document":"12345678901","email":"seller-customer@example.invalid"}');
 cid:=(result->>'id')::uuid;
 ASSERT (SELECT document='12345678901' AND email='seller-customer@example.invalid' AND created_by=seller FROM public.customers WHERE id=cid),'Customer fields not saved';
 args:=jsonb_build_object('p_price_confirmation_supported',true,'p_kind','pre_pedido','p_customer_id',cid,'p_product_id',prod,'p_currency','BRL','p_discount',0,'p_shipping_cost',0,'p_notes','Controlled complete order','p_whatsapp','32988888888','p_items',jsonb_build_array(jsonb_build_object('item_id',item,'quantity',2,'unit_price',100,'discount',0)),'p_payments','[]'::jsonb);
 followup:=jsonb_build_object('seller_id',seller,'warehouse_id',wh,'shipping_address','Rua de teste, 10','shipping_address_number','10','shipping_city','Juiz de Fora','shipping_state','MG','shipping_country','Brasil','shipping_cep','36046040','delivery_recipient_name','Destinatário controlado','delivery_recipient_document','98765432100','order_date',current_date,'delivery_deadline',current_date+5,'carrier','Transportadora teste','tracking_code','CONTROLLED123','variable_cost',0,'item_costs','[]'::jsonb);

 args:=jsonb_set(args,'{p_shipping_cost}','30'); followup:=followup||'{"shipping_mode":"value"}';
 result:=public.integral_seller_create_pdv_order(args,followup,'{"mode":"automatic"}',rid,true); oid:=(result->>'id')::uuid;
 result:=public.integral_seller_create_pdv_order(args,followup,'{"mode":"automatic"}',gen_random_uuid(),true); wrong_order:=(result->>'id')::uuid;
 result:=public.sales_delete_order(wrong_order,'Solicitação duplicada no teste controlado');
 ASSERT (result->>'deleted')::boolean AND (SELECT deleted_at IS NOT NULL FROM public.orders WHERE id=wrong_order),'Own pending request not removed';
 ASSERT EXISTS(SELECT 1 FROM public.order_audit_log WHERE order_id=wrong_order AND action='excluido'),'Removal audit missing';
 ASSERT (SELECT reserved=0 AND quantity=20 FROM public.warehouse_inventory WHERE warehouse_id=wh AND item_id=item),'Pending removal moved stock';
 PERFORM set_config('request.jwt.claim.sub',other_id::text,true);
 BEGIN PERFORM public.sales_delete_order(oid,'Tentativa por outro vendedor'); RAISE EXCEPTION 'Other seller removed order'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.integral_order_credit_context(oid); RAISE EXCEPTION 'Other seller viewed credit'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 PERFORM public.integral_decide_order(oid,'approve','Aprovação controlada para testar pagamentos com frete','policy',NULL,NULL);
 BEGIN PERFORM public.sales_payment_received(jsonb_build_object('order_id',oid,'amount',1,'method','pix'),false); RAISE EXCEPTION 'Legacy receipt entry bypassed review'; EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'Use o botão Lançar pagamento%' THEN RAISE; END IF; END;
 BEGIN PERFORM public.sales_payment_received_manual(jsonb_build_object('order_id',oid,'amount',1,'method','pix'),'{"base":"BRL","mode":"manual","BRL":1,"USD":0.2,"PYG":1400}'); RAISE EXCEPTION 'Legacy manual entry bypassed review'; EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'Use o botão Lançar pagamento%' THEN RAISE; END IF; END;
 BEGIN PERFORM public.sales_register_payment(oid,1,'pix',NULL); RAISE EXCEPTION 'Legacy payment bypassed review'; EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'Use o botão Lançar pagamento%' THEN RAISE; END IF; END;
 PERFORM public.customer_credit_post(cid,'BRL',100,'deposit','Crédito de teste controlado');
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 ASSERT (public.integral_order_credit_context(oid)->>'available')::numeric=100,'Credit balance unavailable';
 result:=public.integral_request_customer_credit(oid,60,credit_request_id,'Uso parcial controlado'); pay1:=(result->>'payment_id')::uuid;
 again:=public.integral_request_customer_credit(oid,60,credit_request_id,'Uso parcial controlado');
 ASSERT result=again,'Credit request retry not idempotent';
 ASSERT (SELECT balance=100 FROM public.customer_credit_accounts WHERE customer_id=cid AND currency='BRL'),'Credit debited before approval';
 ASSERT (SELECT amount_paid=0 AND amount_receivable=230 FROM public.orders WHERE id=oid),'Credit request counted as paid';
 ASSERT (public.integral_order_credit_context(oid)->>'available')::numeric=40,'Pending credit not reserved';
 BEGIN PERFORM public.integral_request_customer_credit(oid,50,gen_random_uuid(),'Reserva acima do disponível'); RAISE EXCEPTION 'Credit double reservation accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'O valor supera o crédito%' THEN RAISE; END IF; END;
 BEGIN PERFORM public.finance_confirm_seller_payment(pay1); RAISE EXCEPTION 'Seller confirmed own credit'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 PERFORM public.finance_confirm_seller_payment(pay1);
 ASSERT (SELECT balance=40 FROM public.customer_credit_accounts WHERE customer_id=cid AND currency='BRL'),'Approved credit not debited exactly';
 ASSERT (SELECT amount_paid=60 AND amount_receivable=170 AND payment_status='parcial' FROM public.orders WHERE id=oid),'Credit approval did not update payment stage';
 PERFORM public.finance_confirm_seller_payment(pay1);
 ASSERT (SELECT count(*)=1 FROM public.customer_credit_entries WHERE payment_id=pay1 AND kind='applied'),'Approval replay spent credit twice';
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 result:=public.integral_request_customer_credit(oid,30,gen_random_uuid(),'Crédito para testar ajuste e recusa');pay2:=(result->>'payment_id')::uuid;
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 PERFORM public.integral_review_payment(pay2,'adjust','Ajuste controlado para vinte',20,current_date,'Crédito do cliente',30);
 ASSERT (SELECT amount=20 AND received_amount=20 FROM public.payments WHERE id=pay2),'Credit adjustment amounts inconsistent';
 ASSERT (SELECT amount=20 FROM private.customer_credit_requests WHERE payment_id=pay2),'Credit reservation did not follow review adjustment';
 PERFORM public.integral_review_payment(pay2,'reject','Recusa controlada do lançamento',NULL,NULL,NULL,20);
 ASSERT (SELECT balance=40 FROM public.customer_credit_accounts WHERE customer_id=cid AND currency='BRL'),'Rejected credit debited balance';
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 ASSERT (public.integral_order_credit_context(oid)->>'available')::numeric=40,'Rejected credit still reserved';
 result:=public.integral_request_customer_credit(oid,20,gen_random_uuid(),'Segundo abatimento controlado');pay3:=(result->>'payment_id')::uuid;
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 INSERT INTO storage.objects(bucket_id,name) VALUES('payment-proofs',oid||'/money.pdf'),('payment-proofs',oid||'/extra.pdf');
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 pay_payload:=jsonb_build_object('received_amount',150,'method','pix','paid_at',current_date,'proof_path',oid||'/money.pdf','notes','Quitação controlada após crédito');
 result:=public.integral_register_payment(oid,gen_random_uuid(),pay_payload); cashpay:=(result->>'payment_id')::uuid;
 ASSERT (SELECT status='pendente' FROM public.payments WHERE id=cashpay),'Money bypassed financial approval';
 ASSERT (SELECT amount_paid=60 FROM public.orders WHERE id=oid),'Pending money/credit changed paid balance';
 BEGIN PERFORM public.integral_register_payment(oid,gen_random_uuid(),pay_payload||jsonb_build_object('received_amount',1,'proof_path',oid||'/extra.pdf')); RAISE EXCEPTION 'Pending entries exceeded free order balance'; EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'O valor supera o saldo livre%' THEN RAISE; END IF; END;
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 PERFORM public.finance_confirm_seller_payment(pay3);
 PERFORM public.finance_confirm_seller_payment(cashpay);
 ASSERT (SELECT total=230 AND shipping_cost=30 AND amount_paid=230 AND amount_receivable=0 AND payment_status='pago' AND commission_total=10 FROM public.orders WHERE id=oid),'Final mixed payment/order/commission state incorrect';
 ASSERT (SELECT balance=20 FROM public.customer_credit_accounts WHERE customer_id=cid AND currency='BRL'),'Mixed payment spent wrong customer credit';
 ASSERT (SELECT sum(amount)=-80 FROM public.customer_credit_entries WHERE customer_id=cid AND kind='applied'),'Credit ledger applied wrong amount';
 PERFORM public.remuneration_close_order(oid,'Conferência controlada do crédito e comprovante');
 ASSERT (SELECT financial_closed_at IS NOT NULL FROM public.orders WHERE id=oid),'Mixed payment could not close';
 -- A previously consumed legacy order must still queue an admin-entered payment, without moving stock again.
 SELECT md5(jsonb_agg(to_jsonb(w) ORDER BY warehouse_id,item_id)::text) INTO stock_before FROM public.warehouse_inventory w;
 INSERT INTO public.orders(id,number,seller_id,customer_id,product_id,warehouse_id,currency,total,amount_paid,amount_receivable,status,kind,stock_state,workflow_stage,payment_status,approval_status,is_demo,order_date,exchange_rates_snapshot,exchange_rate_locked_at)
 VALUES(legacy_order,-2147465000,seller,cid,prod,wh,'BRL',100,0,100,'faturado','venda','baixado','pedido_feito','a_pagar','approved',true,current_date,'{"base":"BRL","BRL":1,"USD":0.2,"PYG":1400}',now());
 INSERT INTO storage.objects(bucket_id,name) VALUES('payment-proofs',legacy_order||'/legacy.pdf');
 result:=public.integral_register_payment(legacy_order,gen_random_uuid(),jsonb_build_object('received_amount',100,'method','transferencia','paid_at',current_date,'proof_path',legacy_order||'/legacy.pdf'));
 legacy_payment:=(result->>'payment_id')::uuid;
 ASSERT (SELECT status='pendente' FROM public.payments WHERE id=legacy_payment),'Admin legacy payment bypassed review';
 ASSERT (SELECT amount_paid=0 FROM public.orders WHERE id=legacy_order),'Admin legacy pending payment changed balance';
 SELECT user_id INTO legacy_actor FROM public.user_roles ur JOIN public.profiles p ON p.id=ur.user_id WHERE ur.role='superadmin' AND p.is_active LIMIT 1;
 PERFORM set_config('request.jwt.claim.sub',legacy_actor::text,true);
 PERFORM public.finance_confirm_seller_payment(legacy_payment);
 ASSERT (SELECT amount_paid=100 AND payment_status='pago' AND stock_state='baixado' FROM public.orders WHERE id=legacy_order),'Legacy payment confirmation failed';
 ASSERT stock_before IS NOT DISTINCT FROM (SELECT md5(jsonb_agg(to_jsonb(w) ORDER BY warehouse_id,item_id)::text) FROM public.warehouse_inventory w),'Legacy confirmation moved stock a second time';
 PERFORM set_config('request.jwt.claim.sub',seller::text,true);
 result:=public.sales_delete_order(oid,'Solicitação controlada de cancelamento de pedido pago');
 ASSERT (result->>'pending')::boolean,'Paid order deleted without cancellation review';
 ASSERT (SELECT deleted_at IS NULL AND amount_paid=230 FROM public.orders WHERE id=oid),'Cancellation request altered paid order';
 ASSERT NOT EXISTS(SELECT 1 FROM private.seller_creation_context WHERE actor=seller),'Seller context leaked';
 ASSERT NOT EXISTS(SELECT 1 FROM private.remuneration_action_context WHERE actor=seller),'Review context leaked';
END $$;
ROLLBACK;
select 'PASS owner removal, safe cancellation, reserved customer credit, review/adjust/reject, mixed money payment, full closure, idempotency and isolation' verification;
